SELECT * FROM menu_item_log
WHERE group_id = #{groupId}

    AND recipe_date = #{menuDate}


    AND user_id = #{operatorId}


    AND item_name LIKE CONCAT('%', #{keyword}, '%')

ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM menu_item_log
WHERE group_id = #{groupId}

    AND recipe_date = #{menuDate}


    AND user_id = #{operatorId}


    AND item_name LIKE CONCAT('%', #{keyword}, '%')

SELECT * FROM menu_item_log
WHERE group_id = #{groupId}

    AND recipe_date >= #{dateFrom}


    AND recipe_date <= #{dateTo}

ORDER BY created_at ASC
